"""Offline, paged evidence browser for the large/multi-page work audit."""
from html import escape

CSS=r'''
:root{--ink:#24364b;--muted:#627387;--line:#d7e0e8;--blue:#175e82;--bg:#edf2f6;--amber:#8c4e11}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font:15px/1.75 system-ui,"Microsoft YaHei",sans-serif}header{background:#17344b;color:white;padding:25px 4vw}h1{font-size:28px;margin:5px 0}h2{font-size:22px;margin:0 0 14px}h3{font-size:17px}header a{color:#d3ebff}a{color:var(--blue)}main{max-width:1550px;margin:auto;padding:22px}section,.card{background:white;border:1px solid var(--line);border-radius:9px;padding:22px;margin:0 0 20px}p{margin:10px 0}code{overflow-wrap:anywhere;background:#e9f0f6;padding:1px 4px}pre{white-space:pre-wrap;overflow-wrap:anywhere;background:#162a3b;color:#e9f2fa;padding:15px;border-radius:5px;max-height:540px;overflow:auto;font:12px/1.65 Consolas,monospace}details{border:1px solid var(--line);border-radius:5px;margin:10px 0;padding:10px 13px}summary{cursor:pointer;font-weight:600}button,input,select{font:inherit;padding:7px 10px;border:1px solid #b1c4d3;border-radius:5px;background:white;color:var(--ink);max-width:100%}button{cursor:pointer}button.active{background:var(--blue);color:white}button:disabled{cursor:default;opacity:.5}.controls{display:flex;flex-wrap:wrap;gap:10px;align-items:center;margin:12px 0}.controls input{flex:1;min-width:180px}.cards{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px}.stat{padding:16px;background:#eef4f8;border-radius:6px;overflow-wrap:anywhere}.stat b{display:block;font-size:27px}.muted{font-size:13px;color:var(--muted)}.warning{background:#fff7e9;border-left:5px solid #bd7b35;padding:16px}.scroll{overflow:auto}table{border-collapse:collapse;width:100%;font-size:14px}th,td{text-align:left;vertical-align:top;padding:10px 12px;border-bottom:1px solid var(--line);overflow-wrap:anywhere}th{background:#edf4f8}ul,ol{padding-left:24px}.split{display:grid;grid-template-columns:minmax(0,1.5fr) minmax(0,1fr);gap:18px}.split>*{min-width:0}.sticky{position:sticky;top:0;background:#f6f9fc;border:1px solid var(--line);padding:12px;z-index:3}.sourceview{position:relative;line-height:0;background:#e7edf2}.sourceview img{width:100%;height:auto;display:block}.sourceview svg{position:absolute;inset:0;width:100%;height:100%}.sourceview rect{fill:#ff9b1f22;stroke:#df7c00;stroke-width:.003}.pill{display:inline-block;background:#edf4f8;border-radius:4px;padding:2px 7px;font-size:12px;margin:2px}.raw{max-height:700px}.flow{display:flex;gap:7px;flex-wrap:wrap}.flow button{background:#eef4f8}.error{color:#a02c23}.hash{font:12px Consolas;overflow-wrap:anywhere}.call-card{margin:9px 0;padding:13px;border:1px solid var(--line);border-radius:5px}.call-card p{margin:5px 0}.linkbutton{border:0;padding:0;color:var(--blue);text-align:left}.trace-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}.trace-grid p{overflow-wrap:anywhere}#unitsList>details{scroll-margin-top:110px}.empty{padding:16px;color:var(--muted)}[hidden]{display:none!important}@media(max-width:850px){.cards,.split,.trace-grid{grid-template-columns:1fr}main{padding:10px}section,.card{padding:16px}h1{font-size:24px}table{min-width:650px}.sticky{position:static}}
'''

JS=r'''
'use strict';
window.WORK_AUDIT_DATASETS={};window.WORK_AUDIT_CALLS={};
const $=id=>document.getElementById(id),M=window.WORK_AUDIT_MANIFEST;
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const pretty=x=>JSON.stringify(x,null,2),num=x=>x==null?'未保存':Number(x).toLocaleString('zh-CN');
const panel=(name,x,open=false)=>`<details ${open?'open':''}><summary>${esc(name)}</summary><pre>${esc(typeof x==='string'?x:pretty(x))}</pre></details>`;
let D=null,U={},E={},callOffset=0,unitOffset=0,factOffset=0,datasetGeneration=0,callGeneration=0;
const pageSize=15;
const scripts=new Map();
function load(url){if(scripts.has(url))return scripts.get(url);const p=new Promise((resolve,reject)=>{const s=document.createElement('script');s.src=url;s.onload=resolve;s.onerror=()=>{scripts.delete(url);reject(Error('文件加载失败：'+url))};document.head.appendChild(s)});scripts.set(url,p);return p;}
function error(e){$('error').textContent=e?.message||String(e);$('error').hidden=false;}
function pane(name){for(const n of ['walk','calls','sources','objects','downstream'])$(n+'Pane').hidden=n!==name;for(const b of document.querySelectorAll('[data-pane]'))b.classList.toggle('active',b.dataset.pane===name);}
function summary(){
 const s=M.summary,h=s.historical_attempts_127;
 $('globalStats').innerHTML=[['127页旧开发累计',`${num(h.requests)}次`,`${num(h.total_tokens)} tokens；不是一轮生产任务`],['8份隔离样例',`${s.synthetic.calls}次`,`${s.synthetic.pages}页，${num(s.synthetic.tokens)} tokens`],['G209知联v3选页',`9次`,'只处理6/127页；不与658直接相除']].map(([a,b,c])=>`<div class="stat">${esc(a)}<b>${esc(b)}</b><span class="muted">${esc(c)}</span></div>`).join('');
 const stages=Object.entries(s.full_stages);$('costRows').innerHTML=stages.map(([k,v])=>`<tr><td>${esc(k)}</td><td>${num(v.requests)}</td><td>${num(v.usage_receipts)}</td><td>${num(v.prompt_tokens)}</td><td>${num(v.completion_tokens)}</td><td>${num(v.total_tokens)}</td></tr>`).join('');
 const verify=stages.filter(([k])=>k.includes('verify')).reduce((n,[,v])=>n+v.requests,0);
 $('costInterpretation').textContent=`核验及归属复核合计${verify}/${h.requests}次（${(verify/h.requests*100).toFixed(1)}%）。这是历史流程中核验工作占比高的证据，不能据此断言全部无用；需要逐项看它纠正了什么。旧快照640个缓存键不等于658次历史尝试，缺失完整输入时不能伪造逐请求重复率。`;
 $('corpusRows').innerHTML=M.datasets.map(s=>{const m=s.metrics;return `<tr><td><button class="linkbutton" data-select="${esc(s.key)}">${esc(s.label)}</button></td><td>${m.processed_pages}/${m.source_pages}</td><td>${m.units}/${m.chunks}</td><td>${m.entity_kinds.entity||0}/${m.entity_kinds.concept||0}</td><td>${m.saved_call_records}记录；${m.saved_inputs}份输入</td><td>${num(m.total_tokens_in_saved_receipts)}</td><td>${m.facts}；待审${m.fact_states.pending||0}</td><td>${m.source_repetition_factor??'无法量测'}倍</td></tr>`}).join('');
 $('synInterpretation').textContent=`隔离样例共${s.synthetic.entities}个主要对象：${s.synthetic.entity_kinds.entity}个具体对象、${s.synthetic.entity_kinds.concept}个概念；${s.synthetic.facts}条事实中，${s.synthetic.fact_owner_kinds.concept}条挂在概念下。后续评估实际引用${s.synthetic.mapping_model_unique_facts}条模型事实，另有${s.synthetic.mapping_local_retrieval_rows}条依靠原文补检。不能用风险接入11例通过，倒推通用识别348条全部正确。未用于评估的知识也不自动等于无用。`;
 $('dataset').innerHTML=M.datasets.map(s=>`<option value="${esc(s.key)}">${esc(s.label)}</option>`).join('');
 $('generated').textContent=M.generated_at;
}
function notes(){
 const common=`当前页面展示保存的原件、预测和调用材料，新增API为0。源码版本、历史输出上限和覆盖范围以本条运行元数据为准。`;
 const map={
 'g209-full':`127页全文保留30个初始分块、94个主要对象和3043条事实。该结果已经过本地归属/契约回放，run.summary.calls=0、receipts为空；658来自另外封存的多轮开发调用审计。没有保存完整请求输入，所以这里能查旧缓存答案和最终证据，不能精确恢复每次发送的上下文或调用顺序。重点检查：同一具体边坡是否出现字段近义重复、概念对象是否重复承接相同事实、核验是否过密。`,
 'g209-six':`本轮真实输入只有第11、12、21、22、38、39页，4个分块、21个主要对象、9次请求。它能展示较新的对象发现/归属/合批重组，但仍非127页整份新版本验收。对照旧全文时，优先看同源内容与归属过程，不把不同页范围和版本的总数量直接相减当准确率。`,
 'D01':`2页只涉及SYN-A、SYN-B两个目标滑坡，但对象发现形成9个主要对象，其中7个是概念。50条来源组成1个分块，之后产生2个重组请求。请选“资料整理与证据复核原则”“图件说明”等对象：可以看到样例中的说明性文字也被组织成独立知识，并占据来源与重组输出。按具体滑坡看，源表与正文又可能产生相近事实；是否应保留取决于知识库用途，不能只数条数。`,
 'D02':`3页只有SYN-C一个目标滑坡，却形成8个主要对象；77条来源、2538字符仍在一个c0001里。因此这里发生的是跨页同块归属，不是跨chunk压力测试。“强发育”在附表，“10人”在另一页：选SYN-C、滑坡发育程度评价、受威胁人数三个对象看，相关信息被分散组织。多个作业的unresolved明确抱怨续行或前置说明不在allowed_span_ids，说明归属选择已经切断完整句子，即使总chunk没超限。`,
 'D03':`本期现状与历史事件要保留不同时间和角色。9个对象中包含历史回顾、本期调查、资料整理和公共背景等概念。后续风险接入补检了原文的本期发育结论；应区分原模型候选、概念归属和补检新增证据，不能把桥接后的成功回写成识别器已经提全。`,
 'D04':`天然现状与暴雨预测并列，不能把预测发育程度用于本期天然现状。5个对象包含一个具体滑坡和4个概念。查看最终事实的role/condition与下游mapping，可看到同一数值是否被放在正确工况，以及哪条发育结论由原文补检进入评估。`,
 'D05':`同一天两组人数来源互相矛盾。这里保留冲突、停止自动取值属于必要工作；不能把未给唯一等级视为无用请求。另一方面，一页内的资料整理原则又被组织成独立概念；需要同时看冲突处理和任务外知识扩张。`,
 'D06':`经济损失量纲换算与横向表格是主要目标，一个具体对象扩张到10个主要对象、50条事实。重点区分模型抽取的原值与下游类型化换算；换算不是再次调用识别模型，也不是模型自己给出的最终国标结果。`,
 'D07':`两页纯扫描，75条OCR来源、一个chunk、两个具体滑坡加两个概念，共3次模型请求。关键失败是归属漏选：SYN-I的“弱发育”在p2ocr4t0，发现/归属输入里有它，重组输入却没有它。SYN-I资料包只给标题和对象行；重组模型因此明确说没有SYN-I发育结论原文。后来风险桥接从p2ocr4t0补检取回。这不是OCR漏字，也不能说是重组模型看到了原文却没提。`,
 'D08':`3页图文混排，两个目标滑坡却形成17个主要对象，其中15个概念，产生3次重组。83条事实里62条挂在概念下。请查看“资料整理说明”“图件说明”“证据与复核说明”等对象对应的输入与输出，再看J/K的评估停止原因。因为发育结论缺失而停止定级是正确边界，不应为追求输出等级而继续调用。`
 };
 $('caseNotes').innerHTML=`<p>${esc(map[D.key]||'')}</p><p class="muted">${esc(common)}</p>`;
 if(D.key==='D07'){
  const id='p2ocr4t0',seen=D.calls.filter(c=>c.span_ids.includes(id));
  $('caseNotes').innerHTML+=`<div class="warning"><h3>把SYN-I这一条掰开看</h3><ol><li>原始OCR单元：<b>${esc(U[id].text)}</b>。<button data-unit="${id}">定位原页并追踪</button></li><li>它进入c0001，发现/归属两次输入都包含这条文字。可打开：${seen.map(c=>`<button data-open-call="${esc(c.key)}">${esc(c.stage)}</button>`).join(' ')}</li><li>归属结果没有把这条来源选入对象/概念的资料包；重组source_spans没有p2ocr4t0。重组模型收到的“弱发育”只有另一个滑坡SYN-H的p1ocr7t0。</li><li>重组响应明确保留：SYN-I的发育程度结论无原文证据。最终原识别结果缺这条SYN-I完整候选。</li><li>后续explicit_source_statement_retrieval从原p2ocr4t0补回“弱发育”。所以评估接入通过，不能把前面的归属缺陷算成识别成功。</li></ol></div>`;
 }
 const m=D.metrics;
 $('flow').innerHTML=[['sources',`${m.processed_pages}页 → ${m.units}来源`],['sources',`${m.chunks}个初始chunk`],['objects',`${m.entities}个主要对象`],['calls',`${m.saved_call_records}份调用记录`],['objects',`${m.facts}事实 / ${m.relations}关系`],['downstream','后续实际接入']].map(([p,t])=>`<button data-pane="${p}">${esc(t)}</button>`).join('');
 $('datasetStats').innerHTML=[['处理范围',`${m.processed_pages}/${m.source_pages}页`],['具体对象/概念',`${m.entity_kinds.entity||0}/${m.entity_kinds.concept||0}`],['待审事实',`${m.fact_states.pending||0}/${m.facts}`],['输入来源重复量',m.source_repetition_factor==null?'缺输入，不能量测':`${m.source_repetition_factor}倍`],['同文来源额外记录',m.literal_duplicate_unit_occurrences],['完全同事实签名额外记录',m.exact_fact_signature_extra_records]].map(([a,b])=>`<div class="stat">${esc(a)}<b>${esc(b)}</b></div>`).join('');
 $('runMeta').innerHTML=panel('完整运行元数据、版本、参数和额外说明',{run:D.run_metadata,extra:D.extra});
 $('chunkRows').innerHTML=D.metrics.chunk_spans.map(c=>`<tr><td>${esc(c.id)}</td><td>${esc(c.pages?.join('、'))}</td><td>${c.units}</td><td>${c.characters}</td><td><button data-chunk="${esc(c.id)}">查看本块全部来源和归属</button></td></tr>`).join('');
 const freq=new Map();for(const c of D.calls)for(const id of c.span_ids)freq.set(id,(freq.get(id)||0)+1);
 $('repeatRows').innerHTML=[...freq].sort((a,b)=>b[1]-a[1]).slice(0,20).map(([id,n])=>`<tr><td><button class="linkbutton" data-unit="${esc(id)}">${esc(id)}</button></td><td>${n}</td><td>${esc(U[id]?.text)}</td></tr>`).join('')||'<tr><td>没有保存请求输入，无法统计这项。不是来源没有重复。</td></tr>';
 $('sourceFrequencyNote').textContent=`计算口径：同一来源ID的文字在已保存输入中出现的次数；去重后来源字符${num(m.unique_input_source_chars)}，各次输入合计${num(m.all_input_source_chars)}，重复部分${num(m.repeated_input_source_chars)}字符。这里只算来源正文，不算提示词/目录，也不是token或费用节省量。跨发现、归属、重组重读有时必要。`;
 $('object').innerHTML='<option value="">全部主要对象</option>'+D.document.entities.map(e=>`<option value="${esc(e.id)}">${esc(e.name)} · ${esc(e.kind)} · ${D.document.facts.filter(f=>f.entity_id===e.id).length}事实</option>`).join('');
 $('apiStage').innerHTML='<option value="">全部阶段</option>'+[...new Set(D.calls.map(c=>c.stage))].map(s=>`<option>${esc(s)}</option>`).join('');
 $('pdfPage').innerHTML=D.page_images.map(p=>`<option value="${p.page}">物理第${p.page}页</option>`).join('');
 $('sourcePdf').href=D.source_pdf;$('sourcePdf').textContent='打开这份原始PDF';$('datasetDownload').href=M.datasets.find(s=>s.key===D.key).json_url;
 $('downstreamBody').innerHTML=D.kind==='synthetic_open_archive'?`<p class="warning">这些是已删除测试数据库留下的历史导出，只用于解释过程。没有恢复数据库，没有重新入库或重新计算。</p><p>下游接入${D.extra.downstream_mapping.length}行：模型事实${D.extra.downstream_mapping.filter(r=>r.source_origin==='knowledge_model_fact').length}，原文补检${D.extra.downstream_mapping.filter(r=>r.source_origin!=='knowledge_model_fact').length}。</p>`+panel('全部下游来源、对象绑定、角色、单位与类型化映射',D.extra.downstream_mapping,true)+panel('保存的下游结果',D.extra.downstream_results):'<p>本条用于识别调用审计，没有在此运行新的风险评估。原有16点诊断或6页检查不能升级为整份正确率。</p>';
 drawCalls();drawUnits();drawFacts();showObject();showPage(D.page_images[0]?.page);
}
async function selectDataset(key){const n=++datasetGeneration;callGeneration++;$('error').hidden=true;$('callDetail').innerHTML='';$('sourceDetail').innerHTML='';$('dataset').value=key;try{const s=M.datasets.find(s=>s.key===key);await load(s.data_url);if(n!==datasetGeneration)return;D=window.WORK_AUDIT_DATASETS[key];U=Object.fromEntries(D.document.units.map(u=>[u.id,u]));E=Object.fromEntries(D.document.entities.map(e=>[e.id,e]));callOffset=unitOffset=factOffset=0;for(const id of ['apiSearch','unitSearch','factSearch'])$(id).value='';$('unitPage').value='0';$('factState').value='';$('object').innerHTML='';$('datasetTitle').textContent=D.label;notes();pane('walk');}catch(e){error(e)}}
function drawCalls(){if(!D)return;const q=$('apiSearch').value.toLowerCase(),stage=$('apiStage').value;const a=D.calls.filter(c=>(!stage||c.stage===stage)&&(!q||JSON.stringify({...c,names:c.subject_ids.map(id=>E[id]?.name)}).toLowerCase().includes(q)));callOffset=Math.min(callOffset,Math.max(0,Math.floor((a.length-1)/pageSize)*pageSize));$('callsList').innerHTML=a.slice(callOffset,callOffset+pageSize).map(c=>`<div class="call-card"><b>${c.ordinal?'回执序号 '+c.ordinal:'缓存记录'} · ${esc(c.stage)} · ${esc(c.status)}</b><p class="muted hash">${esc(c.key)}</p><p>输入${c.input_saved?'已保存':'缺失'}；${c.prompt_chars==null?'提示长度未知':num(c.prompt_chars)+'字符'}；${num(c.usage?.total_tokens)} tokens；来源${c.span_ids.length}次出现；目录${c.registry_entries??'?'}项</p><p class="muted">输出：${esc(pretty(c.output_counts))}；输出上限${c.requested_max_output_tokens??'此条回执未保存'}；${esc(c.finish_reason||'finish_reason未保存')}。这些输出计数不是正确事实数。</p><button data-call="${esc(c.key)}">展开完整请求、响应与来源</button> <a href="${esc(c.raw_url)}">下载完整JSON</a></div>`).join('')||'<p class="empty">没有符合筛选的调用。</p>';$('callsCount').textContent=`${a.length?callOffset+1:0}～${Math.min(a.length,callOffset+pageSize)} / ${a.length}`;$('callPrev').disabled=callOffset===0;$('callNext').disabled=callOffset+pageSize>=a.length;}
async function showCall(key){const c=D.calls.find(c=>c.key===key),n=++callGeneration,dataset=D.key;try{await load(c.detail_url);if(n!==callGeneration||D.key!==dataset)return;const x=window.WORK_AUDIT_CALLS[c.detail_id];$('callDetail').innerHTML=`<h3>${esc(c.stage)} · 完整保存内容</h3><p class="warning">供应商原始HTTP正文未保存。下面cache.answer是解析/校验后对象，不能冒充原始回包。${c.input_saved?'system/prompt为保存的完整输入。':'这条历史完整输入缺失；没有用当前提示词重建冒充。'}</p>`+panel('来源、目录和工作量审计',c,true)+(x.input?panel('完整SYSTEM',x.input.system)+panel('完整PROMPT（含输入JSON）',x.input.prompt)+panel('保存的完整输入对象',x.input):'<p>完整输入未保存。</p>')+panel('完整缓存响应（含answer/invalid_answer/attempts/receipt）',x.cache)+panel('本次记录中的回执',x.receipt_in_run);$('callDetail').scrollIntoView({block:'start'});}catch(e){error(e)}}
function drawUnits(){if(!D)return;const q=$('unitSearch').value.toLowerCase(),page=Number($('unitPage').value);const a=D.document.units.filter(u=>(!page||u.page===page)&&(!q||JSON.stringify(u).toLowerCase().includes(q)));unitOffset=Math.min(unitOffset,Math.max(0,Math.floor((a.length-1)/pageSize)*pageSize));$('unitsList').innerHTML=a.slice(unitOffset,unitOffset+pageSize).map(u=>`<details><summary>${esc(u.id)} · 第${u.page}页 · ${esc(u.source)}</summary><p>${esc(u.text)}</p><button data-unit="${esc(u.id)}">追踪这个来源的归属、API和最终输出</button>${panel('完整来源单元',u)}</details>`).join('')||'<p>没有匹配来源。</p>';$('unitsCount').textContent=`${a.length?unitOffset+1:0}～${Math.min(a.length,unitOffset+pageSize)} / ${a.length}`;$('unitPrev').disabled=unitOffset===0;$('unitNext').disabled=unitOffset+pageSize>=a.length;}
function showUnit(id){const u=U[id];if(!u)return;pane('sources');const owners=D.document.entities.filter(e=>e.unit_ids?.includes(id));const chunks=D.document.chunks.filter(c=>c.unit_ids.includes(id));const calls=D.calls.filter(c=>c.span_ids.includes(id));const facts=D.document.facts.filter(f=>f.evidence?.some(e=>e.span_id===id));$('sourceDetail').innerHTML=`<h3>${esc(id)} · 一条来源完整追踪</h3><p>${esc(u.text)}</p><p>页面${u.page}；进入${chunks.map(c=>esc(c.id)).join('、')}；关联对象${owners.map(e=>esc(e.name)).join('、')||'未归属'}；被${calls.length}份保存输入引用；最终${facts.length}条事实引用。</p><p>${calls.map(c=>`<button data-open-call="${esc(c.key)}">${esc(c.stage)} ${c.ordinal||''}</button>`).join(' ')}</p>`+panel('关联对象完整记录',owners)+panel('包含本来源的完整分块',chunks)+panel('最终引用它的全部事实',facts,true);showPage(u.page,u.bbox);$('sourceDetail').scrollIntoView({block:'start'});}
function showPage(number,box=null){const p=D.page_images.find(p=>p.page===Number(number));if(!p)return;$('pdfPage').value=String(number);$('pdfImage').src=p.url;$('pdfLink').href=D.source_pdf+'#page='+number;$('pdfOverlay').innerHTML=box&&box.length===4?`<rect x="${box[0]}" y="${box[1]}" width="${box[2]-box[0]}" height="${box[3]-box[1]}"/>`:'';}
function drawFacts(){if(!D)return;const q=$('factSearch').value.toLowerCase(),owner=$('object').value,state=$('factState').value;const a=D.document.facts.filter(f=>(!owner||f.entity_id===owner)&&(!state||f.status===state)&&(!q||JSON.stringify(f).toLowerCase().includes(q)));factOffset=Math.min(factOffset,Math.max(0,Math.floor((a.length-1)/pageSize)*pageSize));$('factsList').innerHTML=a.slice(factOffset,factOffset+pageSize).map(f=>`<details><summary>${esc(f.object)} · ${esc(f.field)} = ${esc(f.value)} ${esc(f.unit)} · ${esc(f.status)}</summary><p class="muted">role=${esc(f.role)}；工况=${esc(f.condition)}；时间=${esc(f.time)}；${esc(f.reason)}</p><p>${(f.evidence||[]).map(e=>`<button data-unit="${esc(e.span_id)}">${esc(e.span_id)} · 第${e.page}页</button>`).join(' ')}</p>${panel('完整事实、原文、量义、归属与状态',f,true)}</details>`).join('')||'<p>没有匹配事实。</p>';$('factsCount').textContent=`${a.length?factOffset+1:0}～${Math.min(a.length,factOffset+pageSize)} / ${a.length}`;$('factPrev').disabled=factOffset===0;$('factNext').disabled=factOffset+pageSize>=a.length;}
function showObject(){const id=$('object').value;if(!id){$('objectDetail').innerHTML=panel('全部对象和参考概念',{entities:D.document.entities,references:D.document.references});return;}const e=E[id],jobs=(D.document.synthesis_jobs||[]).filter(j=>j.entity_id===id),calls=D.calls.filter(c=>c.subject_ids.includes(id));$('objectDetail').innerHTML=panel('对象、全部归属来源与未完成原因',e,true)+panel('重组作业与unresolved',jobs,true)+`<p>${calls.map(c=>`<button data-open-call="${esc(c.key)}">${esc(c.stage)} ${c.ordinal||''}</button>`).join(' ')}</p>`;}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.select){selectDataset(b.dataset.select);$('detail').scrollIntoView({block:'start'})}if(b.dataset.pane)pane(b.dataset.pane);if(b.dataset.call)showCall(b.dataset.call);if(b.dataset.openCall){pane('calls');showCall(b.dataset.openCall)}if(b.dataset.unit)showUnit(b.dataset.unit);if(b.dataset.chunk){const c=D.document.chunks.find(c=>c.id===b.dataset.chunk);pane('sources');$('sourceDetail').innerHTML=panel('完整分块、来源ID及归属',c,true)+panel('本块全部来源',c.unit_ids.map(id=>U[id]));$('sourceDetail').scrollIntoView({block:'start'})}});
$('dataset').onchange=()=>selectDataset($('dataset').value);for(const id of ['apiSearch','apiStage'])$(id).oninput=()=>{callOffset=0;drawCalls()};for(const id of ['unitSearch','unitPage'])$(id).oninput=()=>{unitOffset=0;drawUnits()};for(const id of ['factSearch','factState'])$(id).oninput=()=>{factOffset=0;drawFacts()};$('object').onchange=()=>{factOffset=0;showObject();drawFacts()};$('pdfPage').onchange=()=>showPage($('pdfPage').value);
$('callPrev').onclick=()=>{callOffset-=pageSize;drawCalls()};$('callNext').onclick=()=>{callOffset+=pageSize;drawCalls()};$('unitPrev').onclick=()=>{unitOffset-=pageSize;drawUnits()};$('unitNext').onclick=()=>{unitOffset+=pageSize;drawUnits()};$('factPrev').onclick=()=>{factOffset-=pageSize;drawFacts()};$('factNext').onclick=()=>{factOffset+=pageSize;drawFacts()};
summary();const selected=new URLSearchParams(location.search).get('dataset');selectDataset(M.datasets.some(d=>d.key===selected)?selected:'D02');
'''


def write_html(out,manifest):
    body='''<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>知联多页与大文档调用审计</title><style>'''+CSS+'''</style></head><body><header><div>SlopeKG · 知联 Knowledge · 保存产物复盘</div><h1>多页与大文档：到底做了多少工作？</h1><p>原件 → OCR/文字 → 分块 → 对象 → 每次API → 最终事实 → 后续接入。新增模型调用0次。</p><nav><a href="知联流程详解.html">固定流程详解</a>　<a href="知联失败样例.html">固定失败入口</a>　<a href="#detail">直接看中间过程</a></nav><p id="generated"></p></header><main>
<section><h2>先把三个不同规模、不同版本说清楚</h2><div class="cards" id="globalStats"></div><p class="warning">8份隔离资料是2～3页的虚构开放开发样例，合计18页；不是大型真实报告。127页是真实全文旧开发结果；6页是同源知联v3抽样，三者不能当同预算、同版本的准确率对照。隐藏及曾为隐藏集的原件均未进入本页。</p><div class="scroll"><table><thead><tr><th>资料（点击展开）</th><th>已处理/原件页</th><th>来源/初始块</th><th>具体/概念</th><th>调用材料</th><th>保存回执tokens</th><th>事实</th><th>保存输入的来源重复量</th></tr></thead><tbody id="corpusRows"></tbody></table></div></section>
<section><h2>127页旧开发累计：钱和请求主要花在哪</h2><div class="scroll"><table><thead><tr><th>阶段</th><th>尝试请求</th><th>usage回执</th><th>输入tokens</th><th>输出tokens</th><th>总tokens</th></tr></thead><tbody id="costRows"></tbody></table></div><p id="costInterpretation"></p><p>这是封存调用与用量审计，不是服务商账单。4次历史尝试缺usage，不能推断免费，也不能自动重发。当前全文快照的0调用是本地回放，不代表当年免费得到这些知识。</p></section>
<section><h2>隔离报告里的“通过”到底经过了什么</h2><p id="synInterpretation"></p><ol><li>原始识别只有一轮31次请求；before/after/after_final/after_release风险接入阶段复用冻结预测，并非模型反复识别了四轮。</li><li>后续“原文补检”取回了6条输入：SYN-D/E/F/F/G/I的发育结论。它是桥接程序补足，并不证明原识别模型已经完整输出。</li><li>正确保留冲突、区间和缺依据而停止定级，是必要边界；不能按“有没有得到一个等级”衡量调用价值。</li></ol></section>
<section><h2>本页怎样辨认“无用功”</h2><div class="trace-grid"><div><b>可以直接核对的工作量</b><p>请求次数/回执、输入的来源重复量、概念对象数量、同文来源记录、完全相同事实签名的额外记录、最终未接纳与下游实际引用。</p></div><div><b>仍需要判断的价值</b><p>重读来源是否用于纠错；概念是否服务当前用途；同文是必要表头/页眉还是重复正文；待审是否由于真实歧义。没有反事实实测，不把可疑开销直接算成“可省API”。</p></div></div></section>
<section id="detail"><div class="sticky"><label>选择完整案例 <select id="dataset"></select></label><div class="controls"><button data-pane="walk">逐步走读</button><button data-pane="calls">API请求与响应</button><button data-pane="sources">原文、分块与追踪</button><button data-pane="objects">对象与最终事实</button><button data-pane="downstream">后续评估接入</button><a id="datasetDownload">下载该案例全部数据JSON</a></div></div><h2 id="datasetTitle"></h2><p id="error" class="error" hidden></p>
<div id="walkPane"><div id="caseNotes"></div><div id="flow" class="flow"></div><div id="datasetStats" class="cards"></div><div id="runMeta"></div><h3>初始分块范围</h3><div class="scroll"><table><thead><tr><th>块</th><th>物理页</th><th>来源单元</th><th>正文字符</th><th>动作</th></tr></thead><tbody id="chunkRows"></tbody></table></div><h3>哪些来源被反复送入</h3><p id="sourceFrequencyNote" class="muted"></p><div class="scroll"><table><thead><tr><th>来源</th><th>出现次数</th><th>完整原文</th></tr></thead><tbody id="repeatRows"></tbody></table></div></div>
<div id="callsPane" hidden><p>回执序号是保存回执的顺序；旧全文没有逐请求输入时仅按缓存键排列，不伪造时间线。每次请求都可展开完整保存内容。</p><div class="controls"><select id="apiStage"></select><input id="apiSearch" type="search" placeholder="阶段、缓存键或关联对象"></div><div id="callsList"></div><div class="controls"><button id="callPrev">上一批调用</button><span id="callsCount"></span><button id="callNext">下一批调用</button></div><div id="callDetail"></div></div>
<div id="sourcesPane" hidden><div class="split"><div><div class="controls"><input id="unitSearch" type="search" placeholder="搜索完整来源文字、ID、类型"><label>物理页 <input id="unitPage" type="number" min="0" value="0"></label></div><p class="muted">页码0=全部。每批15条，展开可看全部字段。来源编号只在当前文档内解释。</p><div id="unitsList"></div><div class="controls"><button id="unitPrev">上一批来源</button><span id="unitsCount"></span><button id="unitNext">下一批来源</button></div><div id="sourceDetail"></div></div><div><div class="controls"><select id="pdfPage"></select><a id="pdfLink">在PDF中打开此页</a><a id="sourcePdf"></a></div><p class="muted">下图来自实际原件渲染；橙色框为该来源保存的归一化位置。图片可右键打开原尺寸。</p><div class="sourceview"><img id="pdfImage" alt="该案例的原始PDF物理页"><svg id="pdfOverlay" viewBox="0 0 1 1" preserveAspectRatio="none"></svg></div></div></div></div>
<div id="objectsPane" hidden><div class="controls"><select id="object"></select><input id="factSearch" type="search" placeholder="查字段、数值、角色、原因、证据ID"><select id="factState"><option value="">全部状态</option><option>pending</option><option>source_aligned</option><option>verified_model</option><option>rejected</option></select></div><div id="objectDetail"></div><div id="factsList"></div><div class="controls"><button id="factPrev">上一批事实</button><span id="factsCount"></span><button id="factNext">下一批事实</button></div></div>
<div id="downstreamPane" hidden><div id="downstreamBody"></div></div></section>
<section><h2>资料边界与原始入口</h2><p>虚构样例保持archive_only；本次只导出审计展示，没有恢复测试SQLite、没有导入正式数据库。所有历史原件和运行文件只读。当前算法没有因本次审计修改。</p><p><a href="../20261101_复杂PDF国标流程/复杂PDF验证报告.html">原复杂PDF报告</a> · <a href="work_audit_receipt.json">构建读取范围、源哈希与汇总</a></p></section></main><script src="assets/work_audit/manifest.js"></script><script>'''+JS+'''</script></body></html>'''
    (out/'多页与大文档调用审计.html').write_text(body,encoding='utf-8')
